import os
import logging
from pathlib import Path
from src import config

logger = logging.getLogger(__name__)

def resolve_platform_path(path_str: str) -> str:
    """
    Intelligently resolves file paths to handle Docker/Windows mismatches.

    1. Checks if the path exists as-is.
    2. If not, and it looks like a Docker path ('/app/data/...'), attempts to 
       map it to the local project's data directory.
    3. Returns the resolved path if found, or the original path if not (to let downstream handle the error).
    """
    if not path_str:
        return path_str

    # 1. Direct Check
    if os.path.exists(path_str):
        return path_str

    # 2. Docker Path Translation (/app/data -> config.DATA_DIR)
    # Normalize separators for string checking
    normalized = str(path_str).replace('\\', '/')

    if '/app/data/' in normalized:
        # Extract relative part: /app/data/reports/xyz.pdf -> reports/xyz.pdf
        try:
            rel_part = normalized.split('/app/data/', 1)[1]
            local_candidate = config.DATA_DIR / rel_part

            if local_candidate.exists():
                logger.debug(f"Resolved Docker path '{path_str}' to local: '{local_candidate}'")
                return str(local_candidate)
        except Exception:
            pass

    if '/app/output/' in normalized:
        try:
            rel_part = normalized.split('/app/output/', 1)[1]
            local_candidate = config.OUTPUT_DIR / rel_part

            if local_candidate.exists():
                logger.debug(f"Resolved Docker path '{path_str}' to local: '{local_candidate}'")
                return str(local_candidate)
        except Exception:
            pass

    return path_str

